const coverage=$('.mobile-coverage');if(coverage){const input=$('#coverage-town'),result=$('.coverage-result'),image=$('#coverage-image'),regions=$$('[data-region]'),places=$$('#coverage-towns option').map(o=>({name:o.value,state:o.dataset.state,url:o.dataset.url}));function region(value){const la=value==='la';image.src='/assets/'+(la?'service-map-louisiana.svg':'service-map.svg');image.alt=la?'Map of Xpress mobile service in Metairie and New Orleans, Louisiana':'Map of Xpress mobile service areas around Philadelphia, Pennsylvania and Camden, New Jersey';regions.forEach(b=>{const active=b.dataset.region===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}regions.forEach(b=>b.addEventListener('click',()=>region(b.dataset.region)));$('.coverage-search').addEventListener('submit',event=>{event.preventDefault();const query=input.value.trim().toLowerCase();result.replaceChildren();if(!query){result.textContent='Enter your town to find a listed service area.';input.focus();return}const matches=places.filter(p=>p.name.toLowerCase().includes(query));if(!matches.length){const p=document.createElement('p');p.textContent='Your town is not in our listed areas. Call to check mobile service for your address.';const a=document.createElement('a');a.href='tel:+12153971926';a.textContent='Call 215-397-1926';result.append(p,a);return}region(matches[0].state==='LA'?'la':'pa');const intro=document.createElement('p');intro.textContent='Mobile service is listed in '+matches.map(p=>p.name+', '+p.state).join('; ')+'. Call to confirm your address and appointment.';result.append(intro);matches.forEach(place=>{const a=document.createElement('a');a.href=place.url;a.textContent='View '+place.name;const estimate=document.createElement('a');estimate.href='/contact-us/?city='+encodeURIComponent(place.name);estimate.textContent='Request service in '+place.name;result.append(a,estimate)})})}

