const regionInfo={PA:{name:'Pennsylvania',phone:'215-397-1926',tel:'+12153971926'},NJ:{name:'New Jersey',phone:'215-397-1926',tel:'+12153971926'},LA:{name:'Louisiana',phone:'504-688-1477',tel:'+15046881477'}};
