$$('[data-intelligence]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-intelligence]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));$$('[data-intelligence-panel]').forEach(p=>p.hidden=p.dataset.intelligencePanel!==btn.dataset.intelligence)}));

