let step=1,draft='';form.noValidate=true;const error=$('#form-error'),sections=$$('[data-step]',form),serviceNames=Object.fromEntries($$('input[name=service]',form).map(x=>[x.value,x.nextElementSibling.firstChild.textContent]));
const date=$('input[name=date]',form),now=new Date();date.min=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
