$$('[data-next]',form).forEach(b=>b.addEventListener('click',()=>{if(validate())go(Number(b.dataset.next))}));$$('[data-back]',form).forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.back))));
form.addEventListener('submit',async e=>{e.preventDefault();if(step!==3){if(validate())go(step+1);return}renderReview();const d=data(),btn=$('button[type=submit]',form);btn.disabled=true;error.textContent='';try{const r=await fetch('/api/quotes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:d.name,email:d.email,phone:d.phone,city:d.city,state:selectedState,service:serviceNames[d.service]||d.service,message:d.message,date:d.date,time:d.time,website:d.website||''})});const j=await r.json().catch(()=>({}));if(r.status===409){btn.disabled=false;go(2);error.textContent=j.error||'That time is no longer available. Please pick another.';document.querySelector('.xb')?.dispatchEvent(new Event('xb-reload'));return}if(!r.ok)throw new Error(j.error||'fail');try{localStorage.setItem('xp_claim',JSON.stringify({ref:j.ref,token:j.uploadToken,at:Date.now()}))}catch{}let upN=0;if(window.XpPhotos&&window.XpPhotos.picker&&window.XpPhotos.picker.files().length){btn.textContent='Uploading photos…';upN=await window.XpPhotos.uploadPending(j.ref,j.uploadToken)}const done=document.createElement('div');done.className='xp-quote-done';done.setAttribute('role','status');const h=document.createElement('h3');h.textContent='Request received. Thank you!';const p=document.createElement('p');p.textContent='Our team will review it and get back to you with a clear quote. Keep your reference number:';const ref=document.createElement('span');ref.className='ref';ref.textContent=j.ref;const p2=document.createElement('p');p2.textContent=j.hasAccount?'Sign in to track this request and message our team.':'Create a free account to track this quote, see your appointment and message our team anytime.';const cta=document.createElement('div');cta.className='cta';const a1=document.createElement('a');a1.className='xp-btn';a1.href='/account/?mode='+(j.hasAccount?'login':'signup')+'&email='+encodeURIComponent(j.email);a1.textContent=j.hasAccount?'Sign in to my account':'Create my account';const b2=document.createElement('button');b2.type='button';b2.className='xp-btn ghost';b2.setAttribute('data-open-chat','');b2.textContent='Chat with us';cta.append(a1,b2);done.append(h,p,ref);if(upN){const pp=document.createElement('p');pp.textContent=window.XpPhotos.failed?((upN-window.XpPhotos.failed)+' of '+upN+' photos uploaded. You can add the rest from your account or by chat.'):(upN+(upN===1?' photo':' photos')+' uploaded. Thank you.');done.append(pp)}done.append(p2,cta);form.replaceChildren(done);done.scrollIntoView({behavior:'smooth',block:'center'})}catch(err){btn.disabled=false;const recipient='info@xpressgaragedoorservics.com';error.textContent='We could not send this just now. We opened your email app instead, or call us for fast help.';location.href='mailto:'+recipient+'?subject='+encodeURIComponent('Estimate request ['+selectedState+']: '+serviceNames[d.service]+' - '+d.city)+'&body='+encodeURIComponent(draft)}});
$('#copy-request').addEventListener('click',async()=>{const status=$('.copy-status');try{await navigator.clipboard.writeText(draft);status.textContent='Copied. Paste this into an email to info@xpressgaragedoorservics.com.'}catch{const area=document.createElement('textarea');area.value=draft;area.setAttribute('aria-label','Your request — select and copy');area.style.cssText='width:100%;min-height:220px;margin-top:16px';$('.email-fallback').append(area);area.focus();area.select();status.textContent='Select and copy your request below.'}});
